def rle_encode(s):
    """'aaabccc' -> [('a', 3), ('b', 1), ('c', 3)]. Empty string -> []."""
    if not s:
        return []
    out = []
    current = s[0]
    count = 1
    for ch in s[1:]:
        if ch == current:
            count += 1
        else:
            out.append((current, count))
            current = ch
            count = 1
    out.append((current, count))
    return out


def rle_decode(pairs):
    """Inverse of rle_encode: [('a', 3), ('b', 1)] -> 'aaab'."""
    return "".join(ch * n for ch, n in pairs)

