from rle import rle_decode, rle_encode


def test_multi_run_string():
    assert rle_encode("aaabccc") == [("a", 3), ("b", 1), ("c", 3)]


def test_single_character():
    assert rle_encode("x") == [("x", 1)]


def test_empty_string():
    assert rle_encode("") == []
    assert rle_decode([]) == ""


def test_decode_reconstructs():
    assert rle_decode([("a", 3), ("b", 1), ("c", 3)]) == "aaabccc"


def test_round_trip():
    s = "wwwwaaadexxxxxx"
    assert rle_decode(rle_encode(s)) == s

