from rle import rle_decode, rle_encode


def test_returns_list():
    assert isinstance(rle_encode("aaa"), list)


def test_empty():
    assert rle_encode("") == []


def test_decode_returns_string():
    assert isinstance(rle_decode([("a", 2)]), str)


def test_decode_nonempty():
    assert len(rle_decode([("a", 2)])) > 0
